export type ArtifactArtworkId =
  | "rusty-spoon"
  | "bent-dagger"
  | "old-pickaxe"
  | "knight-sword"
  | "friend-shield"
  | "crystal-blade"
  | "moon-hammer"
  | "neon-katana"
  | "arcane-staff"
  | "golden-friend-hammer"
  | "celestial-blade"
  | "the-first-hammer";

export const ARTIFACT_ARTWORK: Readonly<Record<ArtifactArtworkId, string>> = Object.freeze({
  "rusty-spoon": "data:image/webp;base64,",
  "bent-dagger": "data:image/webp;base64,",
  "old-pickaxe": "data:image/webp;base64,",
  "knight-sword": "data:image/webp;base64,",
  "friend-shield": "data:image/webp;base64,",
  "crystal-blade": "data:image/webp;base64,",
  "moon-hammer": "data:image/webp;base64,",
  "neon-katana": "data:image/webp;base64,",
  "arcane-staff": "data:image/webp;base64,",
  "golden-friend-hammer": "data:image/webp;base64,",
  "celestial-blade": "data:image/webp;base64,",
  "the-first-hammer": "data:image/webp;base64,",
});

export function artifactArtwork(id: string) {
  return ARTIFACT_ARTWORK[id as ArtifactArtworkId] ?? null;
}

// Same HQ artwork; undiscovered silhouette is rendered with CSS filtering.
export function artifactSilhouette(id: string) {
  return artifactArtwork(id);
}
